#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    long long target;
    cin >> n >> m >> target;
    vector<vector<long long>> g(n, vector<long long>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> g[i][j];
        }
    }

    long long total = 0;
    unordered_map<long long, int> count;
    for (int top = 0; top < n; top++) {
        vector<long long> colSum(m, 0);
        for (int bottom = top; bottom < n; bottom++) {
            for (int j = 0; j < m; j++) colSum[j] += g[bottom][j];
            count.clear();
            count[0] = 1;
            long long prefix = 0;
            for (int j = 0; j < m; j++) {
                prefix += colSum[j];
                auto it = count.find(prefix - target);
                if (it != count.end()) total += it->second;
                count[prefix]++;
            }
        }
    }
    cout << total << "\n";

    return 0;
}

