import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long target = Long.parseLong(next());
        long[][] g = new long[(int) n][(int) m];
        for (int i = 0; i < g.length; i++) {
            for (int j = 0; j < g[i].length; j++) {
                g[i][j] = Long.parseLong(next());
            }
        }

        long total = 0;
        for (int top = 0; top < n; top++) {
            long[] colSum = new long[(int) m];
            for (int bottom = top; bottom < n; bottom++) {
                for (int j = 0; j < m; j++) colSum[j] += g[bottom][j];
                Map<Long, Integer> count = new HashMap<>();
                count.put(0L, 1);
                long prefix = 0;
                for (int j = 0; j < m; j++) {
                    prefix += colSum[j];
                    total += count.getOrDefault(prefix - target, 0);
                    count.merge(prefix, 1, Integer::sum);
                }
            }
        }
        System.out.println(total);
    }
}
